]$pilot_r3$::jsonb)
), remote_keys AS (
 SELECT 'syllabus_versions'::text AS table_name, jsonb_build_object('id',t.id,'code',t.code) AS key_data FROM public.syllabus_versions t
 UNION ALL
 SELECT 'courses'::text AS table_name, jsonb_build_object('id',t.id,'syllabus_id',t.syllabus_id,'hsk_level',t.hsk_level,'title',t.title,'sort_order',t.sort_order) AS key_data FROM public.courses t
 UNION ALL
 SELECT 'units'::text AS table_name, jsonb_build_object('id',t.id,'course_id',t.course_id,'sort_order',t.sort_order) AS key_data FROM public.units t
 UNION ALL
 SELECT 'lessons'::text AS table_name, jsonb_build_object('id',t.id,'unit_id',t.unit_id,'sort_order',t.sort_order) AS key_data FROM public.lessons t
 UNION ALL
 SELECT 'vocabulary'::text AS table_name, jsonb_build_object('id',t.id,'simplified',t.simplified,'pinyin_marked',t.pinyin_marked,'sense_key',t.sense_key) AS key_data FROM public.vocabulary t
 UNION ALL
 SELECT 'grammar_points'::text AS table_name, jsonb_build_object('id',t.id,'title',t.title,'pattern',t.pattern) AS key_data FROM public.grammar_points t
 UNION ALL
 SELECT 'lesson_quizzes'::text AS table_name, jsonb_build_object('id',t.id,'lesson_id',t.lesson_id,'revision',t.revision) AS key_data FROM public.lesson_quizzes t
 UNION ALL
 SELECT 'quiz_questions'::text AS table_name, jsonb_build_object('id',t.id,'quiz_id',t.quiz_id,'sort_order',t.sort_order) AS key_data FROM public.quiz_questions t
 UNION ALL
 SELECT 'syllabus_vocabulary'::text AS table_name, jsonb_build_object('syllabus_id',t.syllabus_id,'vocabulary_id',t.vocabulary_id) AS key_data FROM public.syllabus_vocabulary t
 UNION ALL
 SELECT 'syllabus_grammar'::text AS table_name, jsonb_build_object('syllabus_id',t.syllabus_id,'grammar_id',t.grammar_id) AS key_data FROM public.syllabus_grammar t
 UNION ALL
 SELECT 'lesson_vocabulary'::text AS table_name, jsonb_build_object('lesson_id',t.lesson_id,'vocabulary_id',t.vocabulary_id) AS key_data FROM public.lesson_vocabulary t
 UNION ALL
 SELECT 'lesson_grammar'::text AS table_name, jsonb_build_object('lesson_id',t.lesson_id,'grammar_id',t.grammar_id) AS key_data FROM public.lesson_grammar t
)
SELECT jsonb_build_object('collisions',coalesce(jsonb_agg(to_jsonb(matches) ORDER BY table_name,collision_kind,incoming_key::text),'[]'::jsonb))
FROM (SELECT i.item->>'table' AS table_name, i.item->>'kind' AS collision_kind,
 i.item->'key' AS incoming_key, i.item->'incoming_revision' AS incoming_revision,
 r.key_data AS existing_catalog_identity
FROM incoming i JOIN remote_keys r ON r.table_name=i.item->>'table'
 AND r.key_data @> (i.item->'key')
) matches;
